package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen1Test {

    @Test
    public void testConstructorAndReadSingleByte() throws IOException {
        byte[] data = new byte[]{(byte) 0xAB, (byte) 0xCD};
        CRC32 crc32 = new CRC32();
        InputStream in = new ByteArrayInputStream(data);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        int firstByte = cis.read();
        Assert.assertEquals(0xAB, firstByte);
        Assert.assertEquals(crc32.getValue(), crc32.getValue()); // Verify state

        int secondByte = cis.read();
        Assert.assertEquals(0xCD, secondByte);

        int endOfStream = cis.read();
        Assert.assertEquals(-1, endOfStream);

        Assert.assertEquals(crc32.getValue(), crc32.getValue());
    }










}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen1Test {



    @Test
    public void testReadWithBuffer() throws IOException {
        byte[] data = "Hello World".getBytes();
        CRC32 crc32 = new CRC32();
        InputStream in = new ByteArrayInputStream(data);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        byte[] buffer = new byte[5];
        int bytesRead = cis.read(buffer);

        Assert.assertEquals(5, bytesRead);
        Assert.assertEquals("Hello", new String(buffer, 0, 5));

        int bytesRead2 = cis.read(buffer, 0, 5);
        Assert.assertEquals(5, bytesRead2);
        Assert.assertEquals(" Worl", new String(buffer, 0, 5));

        int bytesRead3 = cis.read(buffer, 0, 5);
        Assert.assertEquals(2, bytesRead3);
        Assert.assertEquals("d", new String(buffer, 0, 1));
    }








}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen1Test {





    @Test
    public void testSkip() throws IOException {
        byte[] data = new byte[]{1, 2, 3, 4, 5};
        CRC32 crc32 = new CRC32();
        InputStream in = new ByteArrayInputStream(data);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        long skipped = cis.skip(3);
        Assert.assertEquals(3, skipped);

        int nextByte = cis.read();
        Assert.assertEquals(4, nextByte);
    }






}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen1Test {







    @Test
    public void testGetValue() throws IOException {
        byte[] data = new byte[]{0x01, 0x02, 0x03};
        CRC32 crc32 = new CRC32();
        InputStream in = new ByteArrayInputStream(data);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        // Before reading
        long valBefore = cis.getValue();
        Assert.assertEquals(0, valBefore);

        // Read all
        cis.read(data);

        long valAfter = cis.getValue();
        Assert.assertEquals(crc32.getValue(), valAfter);
    }




}

package org.apache.commons.compress.utils;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChecksumCalculatingInputStream_ChecksumCalculatingInputStream_TriageGen1Test {









    @Test
    public void testReadWithOffsetAndLength() throws IOException {
        byte[] data = new byte[]{10, 20, 30, 40, 50};
        CRC32 crc32 = new CRC32();
        InputStream in = new ByteArrayInputStream(data);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc32, in);

        byte[] buffer = new byte[5];
        // Read 2 bytes starting from index 1 of the stream into index 2 of buffer
        int bytesRead = cis.read(buffer, 2, 2);

        Assert.assertEquals(2, bytesRead);
        Assert.assertEquals(20, buffer[2]);
        Assert.assertEquals(30, buffer[3]);
    }


}

